package main

import (
	"fmt"
)

const mod = 998244353

var pow []int64

func initPow(n, k int) {
	pow = make([]int64, k)
	if k > 0 {
		pow[0] = 1
		for i := 1; i < k; i++ {
			pow[i] = (int64(n) * pow[i-1]) % mod
		}
	}
}

func ggt(a, b int64) int64 {
	if a < b {
		return ggt(b, a)
	}
	if b == 0 {
		return a
	}
	return ggt(b, a%b)
}

func lcm(a, b int64) int64 {
	return a * b / ggt(a, b)
}

func gcdRange(n int) int {
	gcdVal := int64(1)
	for i := 1; i <= n; i++ {
		gcdVal = lcm(gcdVal, int64(i))
	}
	return int(gcdVal)
}

func solve(n int, a, x, y int64, k int, M int64) {
	initPow(n, k)

	gcdR := gcdRange(k - 1)

	r := make([][]int64, gcdR)
	for i := range r {
		r[i] = make([]int64, k+1)
	}

	for i := 1; i <= k; i++ {
		for j := 0; j < gcdR; j++ {
			jump := j - (j % (k + 1 - i))
			r[j][i] = (((int64(n-1) * r[j][i-1]) + (r[jump][i-1] + int64(j)*pow[i-1])) % mod)
		}
	}

	var sum int64
	for i := 0; i < n; i++ {
		idx := int(a % int64(gcdR))
		term1 := r[idx][k]
		term2 := ((((a / int64(gcdR)) * int64(gcdR) * int64(k)) % mod) * pow[k-1]) % mod
		sum += term1 + term2
		sum %= mod
		a = (a*x + y) % M
	}

	fmt.Println(sum)
}

